it("vertically centers single-line cells in the 44px row without breaking ellipsis", () => {
    // flex would break text-overflow on bare-text cells (Тип, Материалы) and
    // text-align:right, so block cells are centered via align-content instead
    expect(source).toContain("align-content: center");
    expect(source).not.toMatch(/\.wx-row \.wx-cell[^}]*display: flex/s);
  })

it("feature authority rejects duplicate extractum-telegram resolve nodes", () => {
    const metadata = featureMetadataFixture();
    const directOwnerNode = metadata.resolve.nodes[0];
    metadata.resolve.nodes.push({
      ...directOwnerNode,
      deps: [...directOwnerNode.deps],
      features: [...directOwnerNode.features],
    });
    expect(() => generateFeatureBaseline(metadata)).toThrow(
      /expected one resolved extractum-telegram node, found 2/,
    );
  })

it("feature authority rejects non-array feature definitions", () => {
    const metadata = featureMetadataFixture();
    const client = metadata.packages.find(
      ({ name }) => name === "grammers-client",
    );
    if (!client) throw new Error("missing fixture package");
    client.features.default = null;
    expect(() => generateFeatureBaseline(metadata)).toThrow(
      /feature definition.*string array/,
    );
  })

it("feature authority rejects a revision-matching wrong repository URL", () => {
    const metadata = featureMetadataFixture();
    const client = metadata.packages.find(
      ({ name }) => name === "grammers-client",
    );
    if (!client) throw new Error("missing fixture package");
    client.source =
      "git+https://evil.example/grammers?rev=1f901ce6e973fdcf0e74267f3d8efad5c729daaa#1f901ce6e973fdcf0e74267f3d8efad5c729daaa";
    expect(() => generateFeatureBaseline(metadata)).toThrow(
      /source drifted/,
    );
  })

